import {diagramFor} from './diagrams.js';
import {migrations,rpcTrace,majority,wordCount} from './models.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='jmu-distributed-study-v1';
let chapters=[], lessons=[], method={}, current=null, reviewTab='wrong', labState={}, toastTimer, saveTimer;
const defaults=()=>({version:1,done:[],saved:[],answers:{},notes:{},last:'01-01',theme:'light',font:18});
function cleanState(data){
  const d=defaults(); if(!data||typeof data!=='object')return d;
  for(const k of ['done','saved']) if(Array.isArray(data[k]))d[k]=[...new Set(data[k].filter(x=>typeof x==='string'&&/^\d{2}-\d{2}$/.test(x)))];
  if(data.notes&&typeof data.notes==='object')for(const [k,v]of Object.entries(data.notes))if(/^\d{2}-\d{2}$/.test(k)&&typeof v==='string')d.notes[k]=v.slice(0,50000);
  if(data.answers&&typeof data.answers==='object')for(const [k,v]of Object.entries(data.answers))if(/^\d{2}-\d{2}:\d+$/.test(k)&&Number.isInteger(v)&&v>=0&&v<=10)d.answers[k]=v;
  if(typeof data.last==='string'&&/^\d{2}-\d{2}$/.test(data.last))d.last=data.last;
  d.theme=data.theme==='dark'?'dark':'light';d.font=[16,18,20,22].includes(data.font)?data.font:18;return d;
}
let state;try{state=cleanState(JSON.parse(localStorage.getItem(KEY)));}catch{state=defaults();}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast('浏览器无法保存，请导出学习记录备份。');return false;}}
function applyPrefs(){document.body.classList.toggle('dark',state.theme==='dark');document.documentElement.style.setProperty('--article',`${state.font}px`);}
applyPrefs();
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
const icons={home:'<path d="M3 10 12 3l9 7v11h-6v-7H9v7H3z"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2z"/><path d="M9 3v16m6-14v16" fill="none" stroke="currentColor" stroke-width="1.8"/>',lab:'<path d="M8 2h8v3h-1v6l6 9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2l6-9V5H8zm3 10-4 7h10l-4-7V5h-2z"/>',review:'<path d="M5 3h13a2 2 0 0 1 2 2v16H6a3 3 0 0 1-3-3V5a2 2 0 0 1 2-2m1 14a1 1 0 0 0 0 2h12v-2zm2-9v2h7V8z"/>',note:'<path d="M4 3h16v18H4zm4 5v2h8V8zm0 5v2h8v-2z"/>',search:'<path d="m20 20-5-5m2-6a7 7 0 1 1-14 0 7 7 0 0 1 14 0" fill="none" stroke="currentColor" stroke-width="2"/>',sun:'<path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="12" cy="12" r="4"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18" fill="none" stroke="currentColor" stroke-width="2"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor" aria-hidden="true">${icons[name]||icons.home}</svg>`;
const navs=[['home','学习总览','home'],['map','课程地图','map'],['labs','机制实验室','lab'],['review','理解与复习','review'],['notes','我的笔记','note']];
function chapterFor(l){return chapters.find(c=>c.lessons.some(x=>x.id===l?.id));}
function lessonLink(l){return `#/learn/${l.id}`;}
function sectionHtml(s,i){return `<section class="article-section" id="section-${i}"><h2>${esc(s.title)}</h2>${(s.paragraphs||[]).map(p=>`<p>${esc(p)}</p>`).join('')}${diagramFor(current?.id,s.title)}${s.steps?.length?`<ol>${s.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`:''}${s.table?`<div class="table-wrap"><table><thead><tr>${s.table.headers.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${s.table.rows.map(row=>`<tr>${row.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}${s.callout?`<aside class="callout"><strong>${esc(s.callout.title)}</strong><p>${esc(s.callout.text)}</p></aside>`:''}</section>`;}
function shell(content,route){
  const c=chapterFor(current), progress=Math.round(state.done.filter(id=>lessons.some(l=>l.id===id)).length/lessons.length*100);
  $('#app').innerHTML=`${current?'<div class="reading-line" aria-hidden="true"></div>':''}<div class="shell"><button class="mobile-overlay" data-action="menu" aria-label="关闭导航"></button><aside class="sidebar"><a class="brand" href="#/"><span class="brand-symbol">${icon('map')}</span><span><strong>分布式系统</strong><small>A LEARNING COMPANION</small></span></a><div class="sidebar-scroll"><div class="nav-section-label">你的学习空间</div><nav class="nav" aria-label="主导航">${navs.map(([id,label,ico])=>`<a href="#/${id==='home'?'':id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(ico)}${label}</a>`).join('')}</nav><div class="side-course"><div class="side-course-title">课程章节</div>${chapters.map(ch=>`<a href="${lessonLink(ch.lessons[0])}" class="side-chapter ${c?.id===ch.id?'active':''}"><i>${ch.id}</i>${esc(ch.title)}</a>${c?.id===ch.id?ch.lessons.map(l=>`<a href="${lessonLink(l)}" class="side-lesson ${current?.id===l.id?'active':''}">${esc(l.title)}</a>`).join(''):''}`).join('')}</div></div><div class="side-bottom"><div class="side-meta"><span>已读课时</span><span>${state.done.filter(id=>lessons.some(l=>l.id===id)).length} / ${lessons.length}</span></div><div class="small-progress"><i style="width:${progress}%"></i></div><p>保持好奇，按自己的节奏。</p></div></aside><div class="workspace"><header class="topbar"><button class="mobile-menu icon-button" data-action="menu" aria-label="打开导航">${icon('menu')}</button><div class="crumb">学习手册<span>/</span>${current?'第 '+c.id+' 章':esc(navs.find(x=>x[0]===route)?.[1]||'学习方法')}</div><div class="top-tools"><button class="search-trigger" data-action="search"><span>${icon('search')}搜索课程</span><kbd>Ctrl K</kbd></button><button class="icon-button" data-action="theme" aria-label="切换${state.theme==='dark'?'浅色':'深色'}模式">${icon('sun')}</button></div></header><main id="main" tabindex="-1" class="page ${current?'reader-layout':''}">${content}</main></div></div>`;
  document.body.classList.remove('menu-open'); updateScroll();
}
function network(){return `<figure class="hero-visual"><svg viewBox="0 0 400 290" role="img" aria-label="客户端向三个互联节点发出请求，节点复制数据并协调结果"><defs><pattern id="dots" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r=".7" fill="currentColor" opacity=".13"/></pattern></defs><rect width="400" height="290" fill="url(#dots)"/><g stroke="currentColor" stroke-width="1" fill="none" opacity=".4"><path d="M80 147 200 67 316 147 200 225 80 147 316 147M200 67v158"/><circle cx="200" cy="147" r="108" stroke-dasharray="3 8"/></g><g fill="var(--bg)" stroke="var(--green)" stroke-width="1.5"><rect x="53" y="122" width="54" height="50" rx="5"/><rect x="173" y="42" width="54" height="50" rx="5"/><rect x="289" y="122" width="54" height="50" rx="5"/><rect x="173" y="200" width="54" height="50" rx="5"/></g><g stroke="var(--green)" fill="none" stroke-width="1.5"><path d="M65 138h30m-30 9h30m-30 9h17M185 58h30m-30 9h30m-30 9h17M301 138h30m-30 9h30m-30 9h17M185 216h30m-30 9h30m-30 9h17"/></g><g font-family="ui-monospace,monospace" font-size="9" fill="var(--muted)"><text x="65" y="191">CLIENT</text><text x="180" y="29">NODE A</text><text x="298" y="111">NODE B</text><text x="180" y="270">NODE C</text></g><circle cx="140" cy="107" r="4" fill="var(--clay)"/><circle cx="259" cy="147" r="4" fill="var(--clay)"/><circle cx="200" cy="164" r="4" fill="var(--green)"/><rect x="126" y="173" width="57" height="20" fill="var(--bg)"/><text x="130" y="186" font-size="9" fill="var(--muted)">消息 · 状态</text></svg><figcaption>独立的节点，共同完成一件事。</figcaption></figure>`;}
function home(){
  const last=lessons.find(l=>l.id===state.last)||lessons[0],hasStarted=Object.keys(state.answers).length||state.done.length||Object.keys(state.notes).length;
  shell(`<section class="hero"><div><div class="eyebrow"><i></i>JMU / DISTRIBUTED SYSTEMS</div><h1>把复杂的系统，<br>学成<em>清晰的直觉。</em></h1><p>当一台机器变成一群机器，事情会怎样？<br>沿着问题走进原理，在推演中理解分布式系统。</p><div class="hero-actions"><a class="primary" href="${lessonLink(last)}">${hasStarted?'继续学习':'开启第一课'}<span aria-hidden="true">↗</span></a><a class="text-button" href="#/map">先看完整路线 <span aria-hidden="true">→</span></a></div><div class="chapter-status">${hasStarted?`上次停在 · ${esc(last.title)}`:'8 个章节 · 32 个课时 · 6 个机制实验'}</div></div>${network()}</section><div class="path-strip"><div class="path-item"><span class="path-number">01</span><div><strong>先看见问题</strong><p>从具体场景出发，知道为什么需要它。</p></div></div><div class="path-item"><span class="path-number">02</span><div><strong>再推演过程</strong><p>跟着消息和数据，看清每一步变化。</p></div></div><div class="path-item"><span class="path-number">03</span><div><strong>试着换个条件</strong><p>用实验和问题，检验自己的解释。</p></div></div></div><section><div class="section-heading"><h2>一张有来路的知识地图<small>THE CURRICULUM</small></h2><a href="#/map" class="text-button">展开全部课时 →</a></div><div class="course-grid">${chapters.map(c=>`<a class="chapter-card" href="${lessonLink(c.lessons[0])}"><span class="chapter-number">${c.id}</span><div><h3>${esc(c.title)}</h3><p>${esc(c.question)}</p><div class="chapter-meta"><span>${c.lessons.length} 个课时</span><span>${c.lessons.reduce((a,l)=>a+l.minutes,0)} 分钟参考</span><span class="dot">${state.done.filter(id=>c.lessons.some(l=>l.id===id)).length}/${c.lessons.length} 已读</span></div></div><span class="arrow" aria-hidden="true">↗</span></a>`).join('')}</div></section><footer class="bottom-note"><span>JMU 分布式系统 · 个人学习手册</span><a href="#/method">关于这份手册与学习方法 ↗</a></footer>`,'home');
}
function mapPage(){const stages=[['01—03','先让机器协作','通信与数据位置，是后续机制的前提。',chapters.slice(0,3)],['04—06','再面对不确定性','副本、故障与跨节点更新，共享同一组约束。',chapters.slice(3,6)],['07—08','把机制放回系统','把前面的设计组合起来，看计算框架与新型系统。',chapters.slice(6)]];
  shell(`<div class="eyebrow">THE CURRICULUM</div><h1 class="page-title">每一个机制，都有它的来路。</h1><p class="page-intro">这条路线保留课程的八章体系，把每章改写为相互衔接的问题。可以按顺序学，也可以直接回到卡住的地方。时间仅供安排阅读节奏。</p>${stages.map(([n,t,d,cs])=>`<section class="map-stage"><div class="map-stage-head"><span>${n}</span><h2>${t}</h2></div><p class="lab-caption">${d}</p>${cs.map(c=>`<div class="map-chapter"><div><div class="eyebrow">CHAPTER ${c.id}</div><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p>${c.prerequisites.length?`<p>先修衔接：${esc(c.prerequisites.join('、'))}</p>`:''}</div><div class="lesson-list">${c.lessons.map((l,i)=>`<a href="${lessonLink(l)}"><small class="${state.done.includes(l.id)?'done':''}">${state.done.includes(l.id)?'✓':String(i+1).padStart(2,'0')}</small><span>${esc(l.title)}</span><small>${l.minutes} min</small></a>`).join('')}</div></div>`).join('')}</section>`).join('')}`,'map');}
function quizHtml(l){return `<section id="quiz" class="quiz-block"><h2>换个条件，还能解释吗？</h2><p>可选的理解检验。答案记录在本机，可以随时重新选择。</p>${l.quiz.map((q,i)=>{const selected=state.answers[`${l.id}:${i}`];return `<div class="question"><h3>${i+1}. ${esc(q.question)}</h3>${q.options.map((o,j)=>`<button class="option ${selected===undefined?'':j===q.correct?'correct':j===selected?'wrong':''}" data-answer="${i}" data-option="${j}" aria-pressed="${selected===j}"><span>${String.fromCharCode(65+j)}</span>${esc(o)}</button>`).join('')}${selected!==undefined?`<div class="answer-explanation" role="status"><strong>${selected===q.correct?'这次判断成立':'再沿着过程看一遍'} · 参考答案 ${String.fromCharCode(65+q.correct)}</strong>${esc(q.explanation)}</div>`:''}</div>`;}).join('')}</section>`;}
function learn(id){
  current=lessons.find(l=>l.id===id);if(!current){notFound();return;}state.last=id;persist(); const l=current,c=chapterFor(l),idx=lessons.indexOf(l),done=state.done.includes(id);
  shell(`<article class="article"><div class="article-top"><a class="text-button" href="#/map">← 课程地图</a><div class="reader-tools"><button data-action="font-down" aria-label="缩小正文字号">A−</button><button data-action="font-up" aria-label="放大正文字号">A+</button><button class="${state.saved.includes(id)?'saved':''}" data-action="bookmark">${state.saved.includes(id)?'已收藏':'收藏'}</button><button data-action="focus">${document.body.classList.contains('focus')?'退出专注':'专注阅读'}</button></div></div><div class="eyebrow">CHAPTER ${c.id} / LESSON ${id.split('-')[1]} · ${l.minutes} MIN</div><h1>${esc(l.title)}</h1><p class="article-lead">${esc(l.intro)}</p>${l.sections.map(sectionHtml).join('')}${l.lab?`<section class="article-section" id="experiment"><div class="eyebrow">A SMALL EXPERIMENT</div>${labHtml(l.lab)}</section>`:''}<section class="takeaways" id="takeaways"><h2>把这几条因果关系留下</h2><ul>${l.takeaways.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section><div id="quiz-wrapper">${quizHtml(l)}</div><section class="note-block" id="notes"><h2>写下你自己的解释</h2><textarea id="lesson-note" aria-label="本课笔记" placeholder="哪些过程你已经能解释？还有哪一步没连起来？">${esc(state.notes[id]||'')}</textarea><div class="note-status">仅保存在当前浏览器。可在「我的笔记」中导出备份。</div></section><footer class="lesson-footer">${idx>0?`<a href="${lessonLink(lessons[idx-1])}">← 上一课</a>`:'<a href="#/map">← 完整路线</a>'}<div class="finish-actions"><button class="secondary" data-action="complete">${done?'✓ 已读 · 取消标记':'标记为已读'}</button>${idx<lessons.length-1?`<a class="primary" href="${lessonLink(lessons[idx+1])}">下一课 <span>→</span></a>`:'<a class="primary" href="#/review">进入复习 →</a>'}</div></footer></article><aside class="toc"><strong>这一课的线索</strong>${l.sections.map((s,i)=>`<a href="#section-${i}" data-scroll="section-${i}">${esc(s.title)}</a>`).join('')}${l.lab?'<a href="#experiment" data-scroll="experiment">动手推演</a>':''}<a href="#takeaways" data-scroll="takeaways">留下因果关系</a><a href="#quiz" data-scroll="quiz">检验理解</a><a href="#notes" data-scroll="notes">自己的解释</a></aside>`,'learn');
  wireLabs();
}
const labInfo={rpc:['一次请求，为什么执行了两遍？','RPC RETRY','让回复丢失，再观察重试和请求去重。'],hash:['加一台机器，数据要搬多少？','DATA PLACEMENT','对比取模哈希与一致性哈希的迁移范围。'],replication:['写成功了，为什么还读到旧值？','REPLICATION LAG','控制副本追赶，区分写入成功与读到新值。'],quorum:['坏掉几台，集群才无法决定？','MAJORITY','数一数可用节点与多数派的关系。'], '2pc':['准备好了，为什么还要等待？','TWO-PHASE COMMIT','在投票之后暂停协调者，观察参与者为什么阻塞。'],mapreduce:['词频统计，如何分给多台机器？','MAP / SHUFFLE / REDUCE','跟踪每个词怎样被映射、分组并聚合。']};
function labHtml(type){const [title,kicker,desc]=labInfo[type]||labInfo.rpc;return `<div class="lab-panel" data-lab="${type}"><div class="eyebrow">${kicker}</div><div class="lab-header"><div><h2>${title}</h2><p>${desc}</p></div></div><div class="lab-body" data-lab-body="${type}"></div></div>`;}
function labPage(type){
  if(type&&labInfo[type]){shell(`<a class="text-button" href="#/labs">← 全部实验</a><h1 class="page-title">让一个条件发生变化。</h1><p class="page-intro">先预测结果，再推进一步。这里是离线教学模型，省去了生产系统的网络、存储和性能细节。</p>${labHtml(type)}<div class="section-heading"><h2>回到原理</h2></div><div class="lesson-list">${lessons.filter(l=>l.lab===type).map(l=>`<a href="${lessonLink(l)}"><small>${l.id}</small><span>${esc(l.title)}</span><small>去阅读 →</small></a>`).join('')||'<a href="#/map">在课程地图中寻找相关机制 →</a>'}</div>`,'labs');wireLabs();return;}
  shell(`<div class="eyebrow">THE MECHANISM LAB</div><h1 class="page-title">看见变化，才更容易理解。</h1><p class="page-intro">把回复弄丢、让一个副本落后、加一台机器。每个实验只保留一个关键问题，帮助你沿着消息和状态解释结果。</p><div class="lab-grid">${Object.entries(labInfo).map(([id,[t,k,d]],i)=>`<a class="lab-card" href="#/labs/${id}"><small>EXPERIMENT ${String(i+1).padStart(2,'0')} / ${k}</small><h2>${t}</h2><p>${d}</p><span class="text-button">进入实验 →</span></a>`).join('')}</div>`,'labs');
}
function wireLabs(){document.querySelectorAll('[data-lab]').forEach(el=>renderLab(el.dataset.lab));}
function renderLab(type){
  const el=document.querySelector(`[data-lab-body="${type}"]`);if(!el)return;
  const s=labState[type]??=type==='rpc'?{step:0,drop:true,dedupe:true}:type==='hash'?{n:4,mode:'ring'}:type==='replication'?{leader:1,b:1,c:1,read:'b'}:type==='quorum'?{failed:0}:type==='2pc'?{step:0,crash:false,reject:false}:{text:'data systems data\nsystems scale data'};
  if(type==='rpc'){const trace=rpcTrace(s.drop,s.dedupe);s.step=Math.min(s.step,trace.length-1);const t=trace[s.step];el.innerHTML=`<div class="lab-controls"><label><input type="checkbox" data-control="drop" ${s.drop?'checked':''}>让回复丢失</label><label><input type="checkbox" data-control="dedupe" ${s.dedupe?'checked':''}>按请求 ID 去重</label></div><div class="nodes"><div class="node">客户端<b>${t.clientKnown?'✓':'？'}</b><small>${t.clientKnown?'已收到结果':'等待结果'}</small></div><span class="network-link">⇄</span><div class="node">服务端已选人数<b>${t.value}</b><small>request: enroll-42</small></div></div><div aria-live="polite"><div class="step-index">STEP ${s.step+1} / ${trace.length}</div><h3 class="trace-event">${t.event}</h3><p class="trace-detail">${t.detail}</p></div><div class="step-actions"><button class="primary" data-lab-action="next" ${s.step>=trace.length-1?'disabled':''}>推进一步 →</button><button class="secondary" data-lab-action="reset">重新推演</button></div><p class="lab-caption">教学假设：服务端未崩溃；去重记录可靠保留。真实系统必须处理记录过期、并发以及操作与去重结果的原子性。</p>`;}
  if(type==='hash'){const rows=migrations(s.n,s.mode),moved=rows.filter(r=>r.before!==r.after).length;el.innerHTML=`<div class="lab-controls"><label>定位方式 <select data-control="mode"><option value="ring" ${s.mode==='ring'?'selected':''}>一致性哈希（顺时针后继）</option><option value="modulo" ${s.mode==='modulo'?'selected':''}>取模哈希</option></select></label><label>扩容至 <select data-control="n"><option value="3" ${s.n===3?'selected':''}>3 个节点（基线）</option><option value="4" ${s.n===4?'selected':''}>4 个节点</option><option value="5" ${s.n===5?'selected':''}>5 个节点</option></select></label></div><div class="lab-stat">${moved} / ${rows.length}<small>个示例键需要迁移</small></div><div class="key-grid">${rows.map(r=>`<div class="key-cell ${r.before!==r.after?'moved':''}">${r.key}<small>hash ${r.hash}</small>${r.before} → ${r.after}</div>`).join('')}</div><p class="lab-caption">固定哈希空间 0–99：初始 A=10、B=40、C=75，新增 D=90、E=55。顺时针找第一个节点，越过 99 则回到 0。示例不使用虚拟节点，迁移比例受这组位置与样本影响；一致性哈希不保证单个热点键被分散。</p>`;}
  if(type==='replication'){const read=s[s.read];el.innerHTML=`<div class="nodes"><div class="node">主副本 A<b>v${s.leader}</b><small>已确认的写入</small></div><span class="network-link">→</span><div class="node ${s.b<s.leader?'stale':''}">从副本 B<b>v${s.b}</b><small>${s.b<s.leader?'复制尚未追上':'已追上'}</small></div><div class="node ${s.c<s.leader?'stale':''}">从副本 C<b>v${s.c}</b><small>${s.c<s.leader?'复制尚未追上':'已追上'}</small></div></div><div class="lab-controls"><button class="primary" data-lab-action="write">向 A 写入新版本</button><button class="secondary" data-lab-action="sync-b">投递给 B</button><button class="secondary" data-lab-action="sync-c">投递给 C</button><button class="text-button" data-lab-action="reset">重置</button></div><div class="lab-controls"><label>从哪里读 <select data-control="read"><option value="b" ${s.read==='b'?'selected':''}>从副本 B</option><option value="c" ${s.read==='c'?'selected':''}>从副本 C</option></select></label></div><div class="lab-message" aria-live="polite">读取结果：<strong>v${read}</strong>。${read<s.leader?'A 已确认到 v'+s.leader+'，但当前读取副本尚未收到该版本。':'该副本已追上主副本当前版本。'}</div><p class="lab-caption">教学假设：单主、按版本顺序的异步复制；写入仅由主副本确认。点击投递表示该副本补齐当前版本之前的全部日志。本模型不演示主副本故障和选主。</p>`;}
  if(type==='quorum'){const alive=5-s.failed;el.innerHTML=`<div class="lab-controls"><label for="failed-nodes">不可用节点数 ${s.failed} / 5</label><input id="failed-nodes" data-control="failed" type="range" min="0" max="5" value="${s.failed}"></div><div class="nodes">${Array.from({length:5},(_,i)=>`<div class="node ${i>=alive?'off':''}">节点 ${String.fromCharCode(65+i)}<b>${i>=alive?'×':'✓'}</b></div>`).join('')}</div><div class="lab-stat">${alive} / ${majority(5)}<small>可用票数 / 所需多数票</small></div><div class="lab-message" aria-live="polite">${alive>=3?'还存在一个可互通的多数派，满足这轮投票推进所需的数量条件。':'可用节点不足多数派，这轮决定不能在当前条件下形成。'}</div><p class="lab-caption">假设可用节点彼此互通。任意两个 3/5 多数派至少相交一个节点；但“集合相交”本身不保证共识安全，还需要任期、每任期一票、日志规则与持久化等约束。此处只演示票数条件，不是完整 Raft 模拟器。</p>`;}
  if(type==='2pc'){const stages=[['事务尚未开始','协调者准备询问两个参与者，是否能提交这笔跨库更新。','未准备','未准备'],['参与者写入准备记录',s.reject?'B 无法完成本地操作，投出 No；A 已投 Yes。':'A、B 完成本地检查，将准备状态写入稳定日志并投 Yes。','已准备',s.reject?'投 No':'已准备'],[s.reject?'协调者持久化 Abort 决定':'协调者持久化 Commit 决定',s.reject?'任一参与者投 No，协调者选择回滚。':'收齐两个 Yes 后，协调者先可靠写入全局提交决定；尚未通知参与者。','等待决定',s.reject?'等待回滚':'等待决定'],[s.reject?'所有参与者收到 Abort':'所有参与者收到 Commit',s.reject?'参与者撤销本地修改、释放锁，事务结束。':'参与者根据全局决定提交本地修改、记录结果并释放锁。',s.reject?'已回滚':'已提交',s.reject?'已回滚':'已提交']];const t=stages[s.step];el.innerHTML=`<div class="lab-controls"><label><input type="checkbox" data-control="reject" ${s.reject?'checked':''} ${s.step>0?'disabled':''}>让 B 投 No</label></div><div class="nodes"><div class="node ${s.crash?'off':''}">协调者<b>${s.crash?'×':'C'}</b><small>${s.crash?'已暂停':'可运行'}</small></div><div class="node ${s.step===1||s.step===2?'stale':''}">参与者 A<b>${s.step===3?(s.reject?'↶':'✓'):'…'}</b><small>${t[2]}</small></div><div class="node ${s.step===1||s.step===2?'stale':''}">参与者 B<b>${s.step===3?(s.reject?'↶':'✓'):'…'}</b><small>${t[3]}</small></div></div><div aria-live="polite"><div class="step-index">PHASE ${s.step} / 3</div><h3 class="trace-event">${s.crash?'等待协调者恢复':t[0]}</h3><p class="trace-detail">${s.crash?'已经投 Yes 的参与者无法仅凭准备状态判断全局决定，在这个基础 2PC 模型中继续等待。恢复后读取稳定日志，继续原来的决定。':t[1]}</p></div><div class="step-actions"><button class="primary" data-lab-action="next" ${s.crash||s.step===3?'disabled':''}>推进一步 →</button>${s.step===1||s.step===2?`<button class="secondary" data-lab-action="crash">${s.crash?'恢复协调者':'暂停协调者'}</button>`:''}<button class="text-button" data-lab-action="reset">重置</button></div><p class="lab-caption">此处只暂停协调者，参与者与稳定日志均可靠保留。基础 2PC 可能阻塞；Ready 不是 Commit，投过 Yes 的参与者不能随意超时回滚。真实实现还需处理重启、重传与结果查询。</p>`;}
  if(type==='mapreduce'){const result=wordCount(s.text);el.innerHTML=`<label class="sr-only" for="word-input">用空格分隔的词频输入</label><textarea id="word-input" data-control="text" maxlength="2000">${esc(s.text)}</textarea><div class="lab-controls"><button class="primary" data-lab-action="count">重新计算 →</button><span>以空白分词，英文字母统一小写</span></div><div class="reduce-stages"><div class="reduce-stage"><h3>01 / MAP</h3><pre>${result.words.map(w=>`(${w}, 1)`).join('\n')||'请输入一些词'}</pre></div><div class="reduce-stage"><h3>02 / SHUFFLE</h3><pre>${Object.entries(result.groups).map(([w,v])=>`${w}: [${v.join(', ')}]`).join('\n')||'等待输入'}</pre></div><div class="reduce-stage"><h3>03 / REDUCE</h3><pre>${result.counts.map(([w,n])=>`${w}: ${n}`).join('\n')||'等待输入'}</pre></div></div><p class="lab-caption">输入上限 2000 字符，中文词请用空格分开。Shuffle 将相同键交给同一逻辑分组，本地页面只展示数据变换；真实系统还涉及分区、网络传输、排序、溢写与任务重试。</p>`;}
}
function review(){const wrong=lessons.flatMap(l=>l.quiz.map((q,i)=>({l,q,i,a:state.answers[`${l.id}:${i}`]}))).filter(x=>x.a!==undefined&&x.a!==x.q.correct);const saved=lessons.filter(l=>state.saved.includes(l.id));const answered=Object.keys(state.answers).filter(k=>{const [id,i]=k.split(':');return lessons.find(l=>l.id===id)?.quiz[+i];}).length;
  const body=reviewTab==='wrong'?(wrong.length?wrong.map(({l,q,i,a})=>`<article class="review-card"><small>第 ${chapterFor(l).id} 章 / ${esc(l.title)}</small><h3>${esc(q.question)}</h3><p>你的选择：${esc(q.options[a])}<br>参考答案：${esc(q.options[q.correct])}</p><details><summary class="text-button">展开推理与解析</summary><p>${esc(q.explanation)}</p></details><a class="text-button" href="${lessonLink(l)}">回到这课 →</a></article>`).join(''):empty('暂时没有需要回看的错题',answered?'当前已答题目中没有错题。试着解释改动条件后的结果，再决定是否继续。':'读完一课后，可以自愿做几道理解题。这里会收集需要重看的推理。')):reviewTab==='saved'?(saved.length?`<div class="lesson-list">${saved.map(l=>`<a href="${lessonLink(l)}"><small>${l.id}</small><span>${esc(l.title)}</span><small>回到正文 →</small></a>`).join('')}</div>`:empty('把值得重读的一课留在这里','在课时顶部点击「收藏」，以后就能直接回来。')):`<input class="filter-input" id="term-filter" aria-label="筛选概念卡" placeholder="筛选概念，如：一致性、事务…"><div class="term-grid" id="term-grid">${termCards('')}</div>`;
  shell(`<div class="eyebrow">MAKE THE CONNECTIONS</div><h1 class="page-title">把看过，慢慢变成会用。</h1><p class="page-intro">已尝试 ${answered} 道题，${wrong.length} 道需要回看。一次答对只是当前证据，解释过程和迁移应用仍需要你亲自完成。</p><div class="tabs" role="group" aria-label="复习分类">${[['wrong','需要回看'],['saved','收藏课时'],['terms','概念卡片']].map(([id,t])=>`<button data-review-tab="${id}" class="${reviewTab===id?'active':''}" aria-pressed="${reviewTab===id}">${t}</button>`).join('')}</div>${body}`,'review');
}
function termCards(query){const seen=new Set();return lessons.flatMap(l=>l.terms.map(t=>({...t,lesson:l.id}))).filter(t=>{if(seen.has(t.term))return false;seen.add(t.term);return (t.term+t.definition).toLowerCase().includes(query.toLowerCase());}).map(t=>`<button class="term-card" data-action="flip" aria-expanded="false"><strong>${esc(t.term)}</strong><p hidden>${esc(t.definition)}</p><small>点击展开解释 · ${t.lesson}</small></button>`).join('')||'<p class="text-muted">没有匹配概念，试试更短的关键词。</p>';}
function empty(t,p){return `<div class="empty"><h2>${t}</h2><p>${p}</p><a class="secondary" href="#/map">回到课程地图 →</a></div>`;}
function notesPage(){const notes=lessons.filter(l=>state.notes[l.id]?.trim());shell(`<div class="eyebrow">YOUR OWN WORDS</div><h1 class="page-title">留下自己的解释。</h1><p class="page-intro">解释清楚一条因果关系，比抄下一串定义更有用。这里汇集你在每一课写下的笔记。</p>${notes.length?notes.map(l=>`<article class="note-card"><small>第 ${chapterFor(l).id} 章 / LESSON ${l.id}</small><h3><a href="${lessonLink(l)}">${esc(l.title)} ↗</a></h3><p>${esc(state.notes[l.id])}</p></article>`).join(''):empty('第一条笔记，留给一个真正想通的瞬间。','每一课底部都有自己的笔记区，会自动保存在当前浏览器。')}<div class="data-tools"><button class="secondary" data-action="export">导出学习记录 ↓</button><label class="secondary" for="import-data" style="cursor:pointer">导入备份 ↑</label><input type="file" id="import-data" accept="application/json,.json" hidden><p>包含笔记、已读标记、收藏与答题记录。导入时合并笔记和进度，同一条记录以备份中的内容为准。数据仅存在当前浏览器，清理浏览数据会移除记录。</p></div>`,'notes');}
function methodPage(){shell(`<article class="article" style="max-width:780px;margin:auto"><div class="eyebrow">A NOTE ON LEARNING</div><h1 class="page-title">${esc(method.title||'怎样使用这份学习手册')}</h1><p class="article-lead">${esc(method.intro)}</p>${(method.sections||[]).map(sectionHtml).join('')}<section class="article-section"><h2>这份手册的范围</h2><p>正文依据提供的八章课程 PPT 重组，用具体例子补足关键中间过程，并对影响理解的简化表述核对一手资料。第一版提供 32 个课时与 6 个离线机制模型。模型用于观察因果关系，并未连接真实集群。</p><p>已读标记只表示你选择标记的阅读进度；答题记录也只代表这一次判断。页面不会据此宣布你已掌握这门课。笔记、收藏和答案保存在当前浏览器，可以导出备份。</p></section><a class="primary" href="#/map">回到课程地图 →</a></article>`,'method');}
function notFound(){current=null;shell(empty('这个位置暂时没有内容','可以从课程地图回到完整学习路线。'),'map');}
function render(){const parts=location.hash.replace(/^#\/?/,'').split('/');current=null;document.body.classList.remove('menu-open');if(parts[0]!=='learn')document.body.classList.remove('focus');switch(parts[0]){case'':case'home':home();break;case'map':mapPage();break;case'learn':learn(parts[1]);break;case'labs':labPage(parts[1]);break;case'review':review();break;case'notes':notesPage();break;case'method':methodPage();break;default:notFound();}document.title=`${current?.title||navs.find(x=>x[0]===parts[0])?.[1]||'学习手册'} · 分布式系统`;}
function updateScroll(){const line=$('.reading-line');if(line){const total=document.documentElement.scrollHeight-innerHeight;line.style.transform=`scaleX(${total>0?Math.min(1,scrollY/total):0})`;}}
window.addEventListener('scroll',updateScroll,{passive:true});window.addEventListener('resize',updateScroll);
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main')?.focus({preventScroll:true});});
document.addEventListener('click',e=>{
  if(e.target.closest('.skip-link')){e.preventDefault();$('#main')?.focus();$('#main')?.scrollIntoView();return;}
  const a=e.target.closest('[data-action],[data-answer],[data-scroll],[data-review-tab],[data-lab-action]');if(!a)return;
  if(a.dataset.scroll){e.preventDefault();document.getElementById(a.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}
  if(a.dataset.reviewTab){reviewTab=a.dataset.reviewTab;review();return;}
  if(a.dataset.answer!==undefined&&current){const y=scrollY;state.answers[`${current.id}:${a.dataset.answer}`]=+a.dataset.option;persist();$('#quiz-wrapper').innerHTML=quizHtml(current);window.scrollTo(0,y);return;}
  if(a.dataset.labAction){const type=a.closest('[data-lab]').dataset.lab,s=labState[type],action=a.dataset.labAction;
    if(action==='reset'){delete labState[type];renderLab(type);return;}
    if(action==='next')s.step++;
    if(action==='write')s.leader++;
    if(action==='sync-b')s.b=s.leader;
    if(action==='sync-c')s.c=s.leader;
    if(action==='crash')s.crash=!s.crash;
    if(action==='count')s.text=a.closest('[data-lab]').querySelector('textarea').value;
    renderLab(type);return;
  }
  switch(a.dataset.action){
    case'menu':document.body.classList.toggle('menu-open');break;
    case'search':$('#search-dialog').showModal();$('#search-input').value='';search('');$('#search-input').focus();break;
    case'close-search':$('#search-dialog').close();break;
    case'theme':state.theme=state.theme==='dark'?'light':'dark';applyPrefs();persist();a.setAttribute('aria-label',`切换${state.theme==='dark'?'浅色':'深色'}模式`);break;
    case'font-down':case'font-up':state.font=Math.max(16,Math.min(22,state.font+(a.dataset.action==='font-up'?2:-2)));applyPrefs();persist();toast(`正文字号 ${state.font}px`);break;
    case'bookmark':if(!current)break;state.saved=state.saved.includes(current.id)?state.saved.filter(x=>x!==current.id):[...state.saved,current.id];persist();a.classList.toggle('saved',state.saved.includes(current.id));a.textContent=state.saved.includes(current.id)?'已收藏':'收藏';break;
    case'focus':document.body.classList.toggle('focus');a.textContent=document.body.classList.contains('focus')?'退出专注':'专注阅读';updateScroll();break;
    case'complete':if(!current)break;state.done=state.done.includes(current.id)?state.done.filter(x=>x!==current.id):[...state.done,current.id];persist();a.textContent=state.done.includes(current.id)?'✓ 已读 · 取消标记':'标记为已读';$('.side-meta span:last-child').textContent=`${state.done.length} / ${lessons.length}`;$('.small-progress i').style.width=`${state.done.length/lessons.length*100}%`;toast('阅读标记已更新');break;
    case'flip':{const p=a.querySelector('p');p.hidden=!p.hidden;a.setAttribute('aria-expanded',!p.hidden);a.querySelector('small').textContent=p.hidden?'点击展开解释':'点击收起解释';break;}
    case'export':{const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='JMU-分布式系统-学习记录.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('学习记录已导出');break;}
  }
});
document.addEventListener('input',e=>{
  if(e.target.id==='search-input')search(e.target.value);
  if(e.target.id==='term-filter')$('#term-grid').innerHTML=termCards(e.target.value);
  if(e.target.id==='lesson-note'&&current){const id=current.id;state.notes[id]=e.target.value;clearTimeout(saveTimer);saveTimer=setTimeout(()=>{const ok=persist();const status=$('.note-status');if(status)status.textContent=ok?'已自动保存在当前浏览器。可在「我的笔记」中导出备份。':'浏览器无法保存，请及时导出学习记录。';},350);}
});
document.addEventListener('change',async e=>{
  if(e.target.dataset.control){const type=e.target.closest('[data-lab]').dataset.lab,key=e.target.dataset.control;if(key==='text')return;const s=labState[type];s[key]=e.target.type==='checkbox'?e.target.checked:['n','failed'].includes(key)?+e.target.value:e.target.value;if(type==='rpc')s.step=0;renderLab(type);}
  if(e.target.id==='import-data'){
    const file=e.target.files[0];if(!file)return;if(file.size>2e6){toast('备份超过 2MB，请检查所选文件。');return;}
    try{const raw=JSON.parse(await file.text());if(raw.version!==1||!raw.notes||!Array.isArray(raw.done)||!raw.answers)throw Error();const incoming=cleanState(raw);state={...state,done:[...new Set([...state.done,...incoming.done])],saved:[...new Set([...state.saved,...incoming.saved])],notes:{...state.notes,...incoming.notes},answers:{...state.answers,...incoming.answers}};persist();notesPage();toast('学习记录已合并');}catch{toast('无法读取备份，请选择本网站导出的 JSON 文件。');}
  }
});
function search(query){const q=query.trim().toLowerCase();const matches=q?lessons.filter(l=>[l.title,l.intro,...l.terms.map(t=>t.term),...l.sections.flatMap(s=>[s.title,...s.paragraphs])].join(' ').toLowerCase().includes(q)):lessons.slice(0,5);$('#search-results').innerHTML=matches.length?matches.slice(0,15).map(l=>`<a class="search-result" href="${lessonLink(l)}"><strong>${esc(l.title)}</strong><p>第 ${chapterFor(l).id} 章 · ${esc(l.intro.slice(0,75))}…</p></a>`).join(''):'<p class="lab-caption">没有匹配结果。可以试试「重试」「副本」「共识」。</p>';}
$('#search-results').addEventListener('click',e=>{if(e.target.closest('a'))$('#search-dialog').close();});
$('#search-dialog').addEventListener('click',e=>{if(e.target===$('#search-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search-dialog').showModal();$('#search-input').value='';search('');$('#search-input').focus();}if(e.key==='Escape'){document.body.classList.remove('focus','menu-open');const b=document.querySelector('[data-action="focus"]');if(b)b.textContent='专注阅读';}});
window.addEventListener('pagehide',persist);
try{chapters=await Promise.all(Array.from({length:8},(_,i)=>fetch(`./content/ch${String(i+1).padStart(2,'0')}.json`).then(r=>{if(!r.ok)throw Error('课程文件加载失败');return r.json();})));lessons=chapters.flatMap(c=>c.lessons);method=await fetch('./content/method.json').then(r=>r.json());render();}catch(error){$('#app').innerHTML='<div class="loading">课程暂时未能加载<span>请刷新页面，或检查是否通过本地服务器打开。</span><button class="secondary" onclick="location.reload()">重新加载</button></div>';console.error(error);}
